import { cacheLife, cacheTag } from 'next/cache'
import { SITE_URL, WP_URL } from './site'

/**
 * RSS feed generated by WordPress (/feed/, /news/feed/, /news/category/…/feed/), with links to
 * site pages pointed at this site. Returns null when WordPress has no feed at that path.
 */
export async function getWpFeed(path: string): Promise<string | null> {
  'use cache'
  cacheLife('hours')
  cacheTag('wp', 'wp-posts')
  const res = await fetch(`${WP_URL}/${path ? `${path}/` : ''}feed/`, {
    headers: { Accept: 'application/rss+xml', 'User-Agent': 'Mozilla/5.0 (compatible; ichijoya-next)' },
  })
  if (!res.ok) return null
  const xml = await res.text()
  if (WP_URL === SITE_URL) return xml
  // page links move to this site; /wp/ (uploads, wp-content) stays on WordPress
  return xml.replace(new RegExp(`${WP_URL.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?!/wp/)`, 'g'), SITE_URL)
}
